      "description": "The Republic's principal naval base, a crescent harbor ringed by basalt breakwaters. Its Ledger Hall holds the original Corsair's Code, carved in whale-bone plates."
    },
    {
      "id": "loc_ashen_strait",
      "name": "Ashen Strait",
      "description": "A narrow, fog-choked channel between the two powers. Ancient volcanic vents warm the water, so the fog never lifts and fleets must navigate by bell and lantern."
    },
    {
      "id": "loc_auric_citadel_port",
      "name": "Port Aurelith",
      "description": "The Dominion's gilded fleet harbor, where the admiral's flagship is moored beneath terraced shipyards. The docks stay quiet by decree during the evening watch."
    },
    {
      "id": "loc_drowned_vesper",
      "name": "Drowned Vesper",
      "description": "The half-submerged hometown of the two brothers. Its bell tower still rings at low tide, and neutral ships may anchor here under a truce older than the war."
    },
    {
      "id": "loc_saltglass_reef",
      "name": "Saltglass Reef",
      "description": "A reef of crystalline mineral that refracts lantern light across miles. Signal-keepers on its spires relay coded flashes to both sides, for a price."
    },
    {
      "id": "loc_tarmouth_yards",
      "name": "Tarmouth Yards",
      "description": "A smoky free port where privateers refit, trade writs, and register under the Code. Neither power fully controls it."
    }
  ],
  "factions": [
    {
      "id": "fac_verrane_navy",
      "name": "Verrane Maritime Navy",
      "description": "The Republic's disciplined fleet, run by sealed orders and a culture of understatement. Its officers are sworn to the Code before they are sworn to the state.",
      "location_ids": ["loc_gull_anchorage", "loc_ashen_strait"]
    },
    {
      "id": "fac_auric_armada",
      "name": "Auric Armada",
      "description": "The Dominion's imperial fleet, led by an admiral known for patient, bloodless victories. It prizes order and tribute above plunder.",
      "location_ids": ["loc_auric_citadel_port", "loc_ashen_strait"]
    },
    {
      "id": "fac_ledgerkeepers",
      "name": "Order of Ledgerkeepers",
      "description": "Scribes who maintain and adjudicate the Corsair's Code. They hold no fleet of their own, but their rulings can void a captain's commission.",
      "location_ids": ["loc_gull_anchorage", "loc_drowned_vesper"]
    },
    {
      "id": "fac_lantern_wardens",
      "name": "Lantern Wardens",
      "description": "Neutral signal-keepers of the reef who sell light-codes to any fleet, and whose broken ciphers have decided past battles.",
      "location_ids": ["loc_saltglass_reef", "loc_tarmouth_yards"]
    }
  ],
  "rules": [
    {
      "id": "rul_no_explosive_powder",
      "statement": "No explosive powder exists in this world. Naval weapons are torsion ballistae, tar-fire projectors, grapnels and rams.",
      "category": "technology"
    },
    {
      "id": "rul_code_binds_privateers",
      "statement": "Any vessel flying a registered writ is bound by the Corsair's Code, and breaking it strips the captain of all legal protection at sea.",
      "category": "social"
