      "id": "rul_kin_recusal",
      "statement": "An officer who discovers a blood relative commands an opposing fleet must declare it to the Ledgerkeepers within a tide cycle, or be considered forsworn.",
      "category": "social"
    },
    {
      "id": "rul_tidal_sails",
      "statement": "Ships rely on wind and the predictable twin tides of the strait, so large fleets can only engage on the turn of the tide.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_writing_of_the_code",
      "name": "The Writing of the Code",
      "description": "After the Plunder Years, the Ledgerkeepers carved the first Corsair's Code into whale-bone, binding privateers and navies to common sea law.",
      "era": "Age of Plunder",
      "location_ids": ["loc_gull_anchorage"]
    },
    {
      "id": "evt_truce_of_vesper",
      "name": "The Bell Truce",
      "description": "A fleet burned in sight of Drowned Vesper, and the survivors swore that its bell would mark ground where no blade is drawn.",
      "era": "Age of Plunder",
      "location_ids": ["loc_drowned_vesper"]
    },
    {
      "id": "evt_fog_of_ashen_strait",
      "name": "Battle of the Blind Tide",
      "description": "Two fleets collided in the fog of the strait and fought for a full tide by sound alone. The result was a draw that opened the Long Reckoning.",
      "era": "Long Reckoning",
      "location_ids": ["loc_ashen_strait"]
    },
    {
      "id": "evt_brothers_parting",
      "name": "The Parting at Vesper",
      "description": "Two brothers disputed whether their house should side with the Republic or the Dominion. The elder left for Port Aurelith, and the two never spoke again.",
      "era": "Long Reckoning",
      "location_ids": ["loc_drowned_vesper", "loc_auric_citadel_port"]
    },
    {
      "id": "evt_reef_cipher_breaking",
      "name": "The Cipher Sold Twice",
      "description": "The Lantern Wardens sold the same light-code to both fleets and almost ended the war by accident.",
      "era": "Long Reckoning",
      "location_ids": ["loc_saltglass_reef"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_brothers_command",
      "name": "Brother Against Brother",
      "description": "The Republic's officer must decide whether to declare his kinship, which could end his command, or to keep it secret and face the admiral in battle. Either course may be a breach of the Code.",
      "faction_ids": ["fac_verrane_navy", "fac_auric_armada"]
    },
    {
      "id": "cnf_code_interpretation",
      "name": "The Weight of the Written Word",
      "description": "The Ledgerkeepers are pressed by the Republic to bend the Code against the Dominion, and by the Dominion to void the Republic's writs. Either ruling risks the Code's neutrality.",
      "faction_ids": ["fac_ledgerkeepers", "fac_verrane_navy", "fac_auric_armada"]
    },
    {
      "id": "cnf_light_codes",
      "name": "Light for Hire",
      "description": "Both fleets seek exclusive control of the Lantern Wardens' ciphers, but the Wardens' neutrality is the only thing keeping the Ashen Strait open to trade.",
      "faction_ids": ["fac_lantern_wardens", "fac_auric_armada", "fac_verrane_navy"]
    }
  ]
}

